'use server';

import { createSupabaseAdminClient } from "@/lib/supabase/server";

/**
 * 仮登録情報を全件取得
 */
export async function getTempRegistrations() {
    const supabase = await createSupabaseAdminClient();
    return supabase
        .schema('attendance')
        .from('temp_registrations')
        .select('*')
        .order('created_at', { ascending: false });
}

/**
 * 仮登録トークンから情報を取得
 */
export async function getTempRegistrationByToken(token: string) {
    const supabase = await createSupabaseAdminClient();

    const { data, error } = await supabase
        .schema('attendance')
        .from('temp_registrations')
        .select('*')
        .eq('token', token)
        .single();

    if (error) {
        console.error('Error fetching temp registration:', error);
        return { data: null, error };
    }

    return { data, error: null };
}

/**
 * カードIDで本登録を完了
 */
export async function completeTempRegistration(token: string, cardId: string) {
    const supabase = await createSupabaseAdminClient();

    try {
        // トークンの検証
        const { data: tempReg, error: tempRegError } = await supabase
            .schema('attendance')
            .from('temp_registrations')
            .select('*')
            .eq('token', token)
            .single();

        if (tempRegError || !tempReg) {
            return { success: false, message: '無効なトークンです。' };
        }

        if (tempReg.completed_at) {
            return { success: false, message: 'この登録は既に完了しています。' };
        }

        // カードIDの重複チェック
        const normalizedCardId = cardId.toLowerCase().replace(/:/g, '');

        const { data: existingUser, error: checkError } = await supabase
            .schema('attendance')
            .from('users')
            .select('supabase_auth_user_id')
            .eq('card_id', normalizedCardId)
            .single();

        if (existingUser) {
            return { success: false, message: 'このカードIDは既に使用されています。' };
        }

        // attendance.usersにレコードを作成
        const { error: insertError } = await supabase
            .schema('attendance')
            .from('users')
            .insert({
                supabase_auth_user_id: tempReg.user_id,
                card_id: normalizedCardId,
            });

        if (insertError) {
            console.error('Error inserting user:', insertError);
            return { success: false, message: 'ユーザー登録に失敗しました。' };
        }

        // 仮登録を完了状態に
        const { error: updateError } = await supabase
            .schema('attendance')
            .from('temp_registrations')
            .update({ completed_at: new Date().toISOString() })
            .eq('token', token);

        if (updateError) {
            console.error('Error updating temp registration:', updateError);
        }

        return { success: true, message: '登録が完了しました！' };
    } catch (error) {
        console.error('Error in completeTempRegistration:', error);
        return { success: false, message: '予期しないエラーが発生しました。' };
    }
}

/**
 * 仮登録を削除
 */
export async function deleteTempRegistration(token: string) {
    const supabase = await createSupabaseAdminClient();

    return supabase
        .schema('attendance')
        .from('temp_registrations')
        .delete()
        .eq('token', token);
}

-- Create the attendance schema
create schema if not exists attendance;

-- Grant usage to necessary roles
grant usage on schema attendance to postgres, anon, authenticated, service_role;

-- Set default grants for new tables in the attendance schema
alter default privileges in schema attendance grant all on tables to postgres, anon, authenticated, service_role;
alter default privileges in schema attendance grant all on functions to postgres, anon, authenticated, service_role;
alter default privileges in schema attendance grant all on sequences to postgres, anon, authenticated, service_role;

--
-- attendance.users TABLE
--
create table attendance.users (
    supabase_auth_user_id uuid not null primary key references member.members(supabase_auth_user_id) on delete cascade,
    card_id character varying not null unique,
    created_at timestamp with time zone not null default now(),
    updated_at timestamp with time zone not null default now()
);
alter table attendance.users enable row level security;

create policy "Allow all access to service_role" on attendance.users for all to service_role using (true) with check (true);
create policy "Allow read access to authenticated users" on attendance.users for select to authenticated using (true);


--
-- attendance.attendances TABLE
--
create table attendance.attendances (
    id uuid not null default gen_random_uuid() primary key,
    user_id uuid not null references attendance.users (supabase_auth_user_id) on delete cascade,
    card_id character varying not null,
    "type" character varying not null,
    "timestamp" timestamp with time zone not null default now(),
    date date not null default (now() at time zone 'utc'::text),
    created_at timestamp with time zone not null default now()
);
alter table attendance.attendances enable row level security;
create index idx_attendances_date_user on attendance.attendances using btree (date, user_id);
create index idx_attendances_user_timestamp on attendance.attendances using btree (user_id, "timestamp");

create policy "Allow all access to service_role" on attendance.attendances for all to service_role using (true) with check (true);
create policy "Allow read access to user for their own records" on attendance.attendances for select to authenticated using ((select auth.uid()) = user_id);


--
-- attendance.temp_registrations TABLE
--
create table attendance.temp_registrations (
    id uuid not null default gen_random_uuid() primary key,
    card_id character varying not null,
    qr_token character varying not null,
    expires_at timestamp with time zone not null,
    is_used boolean not null default false,
    accessed_at timestamp with time zone,
    created_at timestamp with time zone not null default now()
);
alter table attendance.temp_registrations enable row level security;

create unique index temp_registrations_card_id_is_used_expires_at_idx on attendance.temp_registrations (card_id, is_used, expires_at);
create unique index temp_registrations_qr_token_key on attendance.temp_registrations using btree (qr_token);
create index idx_temp_registrations_expires on attendance.temp_registrations using btree (expires_at);

create policy "Allow all access to service_role" on attendance.temp_registrations for all to service_role using (true) with check (true);
create policy "Allow read access for all users" on attendance.temp_registrations for select using (true);


--
-- attendance.daily_logout_logs TABLE
--
create table attendance.daily_logout_logs (
    id uuid not null default gen_random_uuid() primary key,
    executed_at timestamp with time zone not null default now(),
    affected_count integer not null,
    status character varying not null
);
alter table attendance.daily_logout_logs enable row level security;
create policy "Allow all access to service_role" on attendance.daily_logout_logs for all to service_role using (true) with check (true);


--
-- Realtime Publication Setup
--
-- temp_registrations テーブルをRealtimeで監視可能にする（QRコード読み取り検知用）
alter publication supabase_realtime add table attendance.temp_registrations;

'use client'

import { completeRegistration, signInWithDiscord } from '@/app/actions';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Icons } from '@/components/icons';
import Link from 'next/link';
import { useSearchParams } from 'next/navigation';
import type { Tables } from '@/lib/types';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { AlertTriangle } from 'lucide-react';
import { useFormStatus } from 'react-dom';
import { FaDiscord } from 'react-icons/fa';

function SubmitButton({ isUpdate }: { isUpdate: boolean }) {
    const { pending } = useFormStatus();
    return (
        <Button type="submit" className="w-full" size="lg" disabled={pending}>
            {pending ? (isUpdate ? "更新中..." : "登録中...") : (isUpdate ? "カードを更新する" : "登録を完了する")}
        </Button>
    );
}

function RegisterForm({ token, isUpdate }: { token: string, isUpdate: boolean }) {
  return (
    <form action={completeRegistration} className="space-y-4">
      <input type="hidden" name="token" value={token} />
       <div className='text-sm text-muted-foreground text-center'>
        ユーザー情報を確認しました。下のボタンを押して、このカードの{isUpdate ? "更新" : "登録"}を完了してください。
      </div>
      <SubmitButton isUpdate={isUpdate} />
    </form>
  );
}

type FullProfile = Tables<'member', 'members'> & {
    attendance_user: { card_id: string } | null,
    teams: { name: string } | null,
};

export default function RegisterPageClient({ 
    token, 
    tempReg, 
    session, 
    displayName,
    existingCardId,
}: { 
    token: string,
    tempReg?: Tables<'attendance', 'temp_registrations'> | null,
    session?: any,
    displayName?: string | null,
    existingCardId?: string | null,
}) {
    const searchParams = useSearchParams();
    const success = searchParams.get('success');
    const error = searchParams.get('error');
    const newCardId = searchParams.get('newCardId');

    const isUpdateFlow = !!existingCardId && existingCardId !== tempReg?.card_id;

    if (token === 'card-unregistered') {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen bg-background p-4">
                <Card className="w-full max-w-md">
                    <CardHeader className="items-center text-center">
                        <AlertTriangle className="w-16 h-16 text-orange-500 mb-4" />
                        <CardTitle className="text-2xl">カードが未登録です</CardTitle>
                        <CardDescription>
                            出退勤の記録にはカードの登録が必要です。
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="text-center space-y-4">
                        <p className="text-muted-foreground">
                            旧システムからカードIDを引き継ぐか、部室のKiosk端末でカードをスキャンして登録してください。
                        </p>
                        <div className="space-y-2">
                            <Button asChild className="w-full">
                                <Link href="/dashboard">ダッシュボードで旧カードを引き継ぐ</Link>
                            </Button>
                        </div>
                        <Button asChild variant="ghost" className="w-full">
                            <Link href="/login">ログインページに戻る</Link>
                        </Button>
                    </CardContent>
                </Card>
            </div>
        );
    }

    if (success === 'true') {
        const cardId = newCardId || tempReg?.card_id || '';
        const discordUsername = session?.user?.user_metadata?.user_name || session?.user?.user_metadata?.full_name || '';
        const userName = displayName || '名無しさん';

        return (
            <div className="flex flex-col items-center justify-center min-h-screen bg-background p-4">
                <Card className="w-full max-w-md">
                    <CardHeader className="items-center text-center">
                        <Icons.CheckCircle2 className="w-16 h-16 text-green-500 mb-4" />
                        <CardTitle className="text-2xl">{isUpdateFlow ? "カードが更新されました！" : "登録が完了しました!"}</CardTitle>
                        <CardDescription>ダッシュボードへ移動できます</CardDescription>
                    </CardHeader>
                    <CardContent className='space-y-4'>
                        <Card className='bg-muted/50'>
                           <CardContent className='p-4 space-y-2'>
                                <div className="flex justify-between items-center">
                                    <span className='font-semibold'>お名前</span>
                                    <span className='font-medium'>{userName}</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className='font-semibold'><FaDiscord className="inline w-4 h-4 mr-1" />Discord ユーザー名</span>
                                    <span className='font-medium'>@{discordUsername}</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className='font-semibold'>カードID</span>
                                    <span className='font-mono text-sm'>{cardId}</span>
                                </div>
                           </CardContent>
                        </Card>
                        <Button asChild className="w-full"><Link href="/dashboard">ダッシュボードへ</Link></Button>
                    </CardContent>
                </Card>
            </div>
        );
    }

    if (!tempReg || tempReg.is_used || new Date(tempReg.expires_at) < new Date()) {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen bg-background p-4">
                <Card className="w-full max-w-md">
                    <CardHeader className="items-center text-center">
                        <Icons.XCircle className="w-16 h-16 text-destructive mb-4" />
                        <CardTitle className="text-2xl">登録エラー</CardTitle>
                        <CardDescription>
                            {tempReg?.is_used ? "この登録リンクは既に使用されています。" : "この登録リンクは無効か、有効期限が切れています。"}
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <p className="text-center text-muted-foreground">お手数ですが、もう一度Kiosk端末でQRコードを生成してください。</p>
                    </CardContent>
                </Card>
            </div>
        );
    }

    return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-background p-4">
            <Card className="w-full max-w-md">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2 text-2xl"><Icons.UserPlus /> {isUpdateFlow ? "カードの更新" : "カード登録"}</CardTitle>
                    <CardDescription>QRコードスキャンありがとうございます。Discordで認証して登録を完了してください。</CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                    {error && (
                        <Alert variant="destructive">
                            <AlertTriangle className="h-4 w-4" />
                            <AlertTitle>登録エラー</AlertTitle>
                            <AlertDescription>{error}</AlertDescription>
                        </Alert>
                    )}
                    <Card className="bg-muted/50">
                        <CardContent className="p-4 space-y-2 text-sm">
                            {session?.user?.user_metadata && displayName && (
                                <div className="flex justify-between">
                                    <span className="text-muted-foreground">お名前:</span>
                                    <span className="font-medium">{displayName}</span>
                                </div>
                            )}
                            {session?.user?.user_metadata && (
                                <div className="flex justify-between">
                                    <span className="text-muted-foreground flex items-center gap-1"><FaDiscord className="w-4 h-4"/>Discord ユーザー名:</span>
                                    <span className="font-medium">{session.user.user_metadata.user_name || session.user.user_metadata.full_name}</span>
                                </div>
                            )}
                             <div className="flex justify-between">
                                <span className="text-muted-foreground">新しいカードID:</span>
                                <span className="font-mono font-medium">{tempReg.card_id}</span>
                            </div>
                            {isUpdateFlow && (
                                <div className="flex justify-between">
                                    <span className="text-muted-foreground">現在のカードID:</span>
                                    <span className="font-mono font-medium text-destructive line-through">{existingCardId}</span>
                                </div>
                            )}
                        </CardContent>
                    </Card>

                    {!session ? (
                        <form action={signInWithDiscord}>
                            <input type="hidden" name="next" value={`/register/${token}`} />
                            <Button type="submit" className="w-full bg-[#5865F2] hover:bg-[#4752C4] text-white" size="lg">
                                <FaDiscord className="w-5 h-5 mr-2" />
                                Discordで認証して{isUpdateFlow ? "更新" : "登録"}する
                            </Button>
                        </form>
                    ) : (
                        <RegisterForm token={token} isUpdate={isUpdateFlow} />
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

